import{at as e,it as t,n,vt as r}from"./chunks/framework.B6nQ8gjX.js";var i=JSON.parse(`{"title":"翻译选项","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/translation-options.md","filePath":"zh/guide/translation-options.md"}`),a={name:`zh/guide/translation-options.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="翻译选项" tabindex="-1">翻译选项 <a class="header-anchor" href="#翻译选项" aria-label="Permalink to “翻译选项”">​</a></h1><p>本文档对应 Zotero PDF2zh <strong>v4.1.1</strong>（含 v4.1.0 功能）。</p><p>在 Zotero 中选中论文条目或 PDF 附件，右键打开「PDF2zh」菜单。</p><p>v4.1.0 起会识别附件当前状态，避免把已经处理过的 PDF 再次送入不兼容操作。</p><h2 id="pdf-状态" tabindex="-1">PDF 状态 <a class="header-anchor" href="#pdf-状态" aria-label="Permalink to “PDF 状态”">​</a></h2><p>可以把常见流程理解为：</p><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>origin</span></span>
<span class="line"><span>→ mono / dual(LR/TB)</span></span>
<span class="line"><span>→ mono-cut / dual-cut / compare / crop-compare</span></span></code></pre></div><p>其中 <code>compare</code> 和 <code>crop-compare</code> 是终态结果；如果再次执行同一操作，插件会在上传前直接提示，不会生成重复附件。</p><h2 id="翻译-pdf" tabindex="-1">翻译 PDF <a class="header-anchor" href="#翻译-pdf" aria-label="Permalink to “翻译 PDF”">​</a></h2><p><strong>输入：</strong> 原始 PDF / 论文条目。</p><p>根据插件设置生成 mono、dual 以及用户启用的附加输出。</p><p>对已经生成的 mono / dual / compare / crop-compare 再执行「翻译 PDF」会被拒绝；需要重新翻译时请回到原始附件。</p><h2 id="裁剪-pdf-crop" tabindex="-1">裁剪 PDF（Crop） <a class="header-anchor" href="#裁剪-pdf-crop" aria-label="Permalink to “裁剪 PDF（Crop）”">​</a></h2><p><strong>支持输入：</strong></p><ul><li>origin</li><li>mono</li><li>dual</li></ul><p>输出通常为：</p><ul><li><code>mono-cut</code></li><li><code>dual-cut</code></li></ul><p>对于 <code>pdf2zh_next</code> 的 <strong>LR dual（左右同页）</strong>，v4.1.0 会先在内部规范化为适合裁剪的 TB/交替页结构，然后继续完成真正的 <code>dual-cut</code>。</p><p>因此：</p><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>LR dual</span></span>
<span class="line"><span>→ 内部 LR→TB</span></span>
<span class="line"><span>→ 真正裁剪</span></span>
<span class="line"><span>→ dual-cut</span></span></code></pre></div><p>不会再把「LR→TB」本身错误当作 Crop 的最终结果。</p><div class="tip custom-block"><p class="custom-block-title">适用场景</p><p>Crop 主要用于把双栏论文拆成更适合窄屏阅读的单栏结构。</p></div><h2 id="双语对照-compare" tabindex="-1">双语对照（Compare） <a class="header-anchor" href="#双语对照-compare" aria-label="Permalink to “双语对照（Compare）”">​</a></h2><p><strong>支持输入：</strong></p><ul><li>origin</li><li>dual</li></ul><p>输出 <code>compare</code>。</p><p>如果输入是原文，Server 会先生成需要的 dual，再完成对照布局。</p><p><code>compare</code> 是终态；对 <code>compare</code> 再执行 Compare 会直接提示选择原文或 dual。</p><h2 id="双语对照-裁剪后拼接-crop-compare" tabindex="-1">双语对照（裁剪后拼接 / Crop-Compare） <a class="header-anchor" href="#双语对照-裁剪后拼接-crop-compare" aria-label="Permalink to “双语对照（裁剪后拼接 / Crop-Compare）”">​</a></h2><p><strong>支持输入：</strong></p><ul><li>origin</li><li>dual</li><li>dual-cut</li></ul><p>适合双栏论文：先规范化/裁剪成单栏，再生成双语对照结果。</p><p>对于 LR dual：</p><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>LR dual</span></span>
<span class="line"><span>→ 内部 LR→TB</span></span>
<span class="line"><span>→ 真正 crop-compare</span></span>
<span class="line"><span>→ crop-compare</span></span></code></pre></div><p>v4.1.0 不会再出现“第一次 Crop-Compare 只把左右布局变成交替页，却把文件命名成 crop-compare”的问题。</p><p><code>crop-compare</code> 也是终态。再次执行 Crop-Compare 时，插件和 Server 都会拒绝该操作。</p><h2 id="lr-与-tb-是什么" tabindex="-1">LR 与 TB 是什么？ <a class="header-anchor" href="#lr-与-tb-是什么" aria-label="Permalink to “LR 与 TB 是什么？”">​</a></h2><h3 id="lr-side-by-side" tabindex="-1">LR / Side by Side <a class="header-anchor" href="#lr-side-by-side" aria-label="Permalink to “LR / Side by Side”">​</a></h3><p>原文和译文在同一页左右排列。</p><h3 id="tb-alternating-pages" tabindex="-1">TB / Alternating Pages <a class="header-anchor" href="#tb-alternating-pages" aria-label="Permalink to “TB / Alternating Pages”">​</a></h3><p>原文页与译文页交替出现。</p><div class="info custom-block"><p class="custom-block-title">历史名称</p><p>旧界面曾把 TB 写成“Top &amp; Bottom / 上下对照”。当前 <code>pdf2zh_next</code> / BabelDOC 中它实际表示 <strong>Alternating Pages</strong>，不是同页上下排列。</p></div><h2 id="什么时候应该回到原文" tabindex="-1">什么时候应该回到原文？ <a class="header-anchor" href="#什么时候应该回到原文" aria-label="Permalink to “什么时候应该回到原文？”">​</a></h2><p>如果您想：</p><ul><li>改翻译模型；</li><li>改语言；</li><li>改 Thinking 设置；</li><li>重新生成不同布局；</li><li>对已经是 compare / crop-compare 的文件重新处理；</li></ul><p>推荐直接选择原始 PDF 或原始 dual，而不是把后处理结果继续链式加工。</p><h2 id="批量处理" tabindex="-1">批量处理 <a class="header-anchor" href="#批量处理" aria-label="Permalink to “批量处理”">​</a></h2><p>可以多选多个条目或附件执行同一种操作。</p><p>v4.1.0 修复了批处理统计：单个文件失败会计入 <code>failed</code>，不会再因为内部异常被吞掉而错误显示为成功；每次批处理完成后事件监听器也会释放。</p><h2 id="操作选择建议" tabindex="-1">操作选择建议 <a class="header-anchor" href="#操作选择建议" aria-label="Permalink to “操作选择建议”">​</a></h2><table tabindex="0"><thead><tr><th>需求</th><th>推荐</th></tr></thead><tbody><tr><td>普通翻译</td><td>翻译 PDF</td></tr><tr><td>小屏/手机单栏阅读</td><td>Crop</td></tr><tr><td>原译文对照</td><td>Compare</td></tr><tr><td>双栏论文裁剪后对照</td><td>Crop-Compare</td></tr><tr><td>已经生成终态但想重做</td><td>回到原文/dual 重新生成</td></tr></tbody></table><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to “相关文档”">​</a></h2><ul><li><a href="/zh/guide/configuration.html">配置说明</a></li><li><a href="/zh/guide/installation.html">安装指南</a></li><li><a href="/zh/guide/package-update.html">翻译环境更新</a></li></ul>`,53)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};